import sys
from collections import deque

def findShortestPath(matrix):
    if not matrix or not matrix[0]:
        return -1

    rows, cols = len(matrix), len(matrix[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_safe(x, y, visited):
        return 0 <= x < rows and 0 <= y < cols and matrix[x][y] == 1 and not visited[x][y]

    def bfs(start_x, start_y, visited):
        queue = deque([(start_x, start_y, 1)])
        visited[start_x][start_y] = True

        while queue:
            x, y, dist = queue.popleft()

            if y == cols - 1:
                return dist

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_safe(nx, ny, visited):
                    visited[nx][ny] = True
                    queue.append((nx, ny, dist + 1))

        return -1

    min_path = sys.maxsize
    found_path = False

    for i in range(rows):
        if matrix[i][0] == 1:
            visited = [[False] * cols for _ in range(rows)]
            path_length = bfs(i, 0, visited)
            if path_length != -1:
                found_path = True
                min_path = min(min_path, path_length)

    return min_path if found_path else -1

def main():
    import sys
    input = sys.stdin.read().strip().split('\n')
    matrix = [list(map(int, row.split())) for row in input]
    result = findShortestPath(matrix)
    print(result)

if __name__ == "__main__":
    main()
